package de.jflex.testing.scan;

/**
 * The methods of a generated scanner that the assertions of {@link ScannerTest} read. Use with
 *
 * <pre>
 * %implements de.jflex.testing.scan.TestScanner
 * </pre>
 *
 * <p>The methods for the position are generated by {@code %counter_methods}, for the counters that
 * the spec turns on with {@code %line}, {@code %column} and {@code %char}. The default methods here
 * stand in for the others and throw when a test asks for a counter that the scanner does not have.
 *
 * <p>{@code yylex()} is not part of the interface, because its return type depends on the spec.
 *
 * @see ScannerTest
 */
public interface TestScanner {

  /** Returns the text of the current match. */
  String yytext();

  /** Returns the length of the current match. */
  int yylength();

  /** Returns whether the scanner has reached the end of its input. */
  boolean yyatEOF();

  /** Returns the line of the current match, counted from 0. */
  default int yyline() {
    throw missing("yyline()", "%line");
  }

  /** Returns the column of the current match, counted from 0. */
  default int yycolumn() {
    throw missing("yycolumn()", "%column");
  }

  /** Returns the offset of the current match from the start of the input, counted from 0. */
  default long yychar() {
    throw missing("yychar()", "%char");
  }

  /** The exception for a counter method that the scanner does not have. */
  default UnsupportedOperationException missing(String method, String directive) {
    return new UnsupportedOperationException(
        getClass().getName()
            + " has no "
            + method
            + ". The spec needs "
            + directive
            + " and %counter_methods.");
  }
}
